const islandAssets=['forest','castle','robot','detective'];
const islandPixels=new Map();let mapMotionPaused=false,selectedIsland=false;
function animatedIslandMarkup(w,i){return `<div class="island-unit unit-${i}" style="--delay:${-i*1.7}s;--glow:${['#cfff77','#e1b5ff','#72f5ff','#ffd47d'][i]}"><div class="island-floating"><span class="island-aura" aria-hidden="true"></span><button class="island-surface" data-island="${i}" aria-label="${i<2?'Chơi':'Xem thông tin'} ${w[0]}" onclick="activateIsland(event,${i})"><img class="island-sprite" src="assets/island-${islandAssets[i]}.png" alt="" draggable="false"><span class="island-ripple" aria-hidden="true"></span></button><div class="island-label" aria-hidden="true"><span class="island-number">${i<2?'✦':'🔒'} ${String(i+1).padStart(2,'0')}</span><span class="island-name">${w[0]}</span><span class="island-caption">${i<2?`${count(i)}/4 thử thách · Khám phá →`:'Đang xây dựng'}</span></div><div class="island-particles" aria-hidden="true">${Array.from({length:6},(_,k)=>`<i style="--n:${k}">✦</i>`).join('')}</div></div></div>`}
function alphaAt(button,event){const img=button.querySelector('img'),p=islandPixels.get(img.getAttribute('src'));if(!p)return false;const r=img.getBoundingClientRect(),scale=Math.min(r.width/p.w,r.height/p.h),dw=p.w*scale,dh=p.h*scale,x=(event.clientX-r.left-(r.width-dw)/2)/scale,y=(event.clientY-r.top-(r.height-dh)/2)/scale;const radius=7/scale;for(const [dx,dy] of [[0,0],[radius,0],[-radius,0],[0,radius],[0,-radius]]){const px=Math.round(x+dx),py=Math.round(y+dy);if(px>=0&&py>=0&&px<p.w&&py<p.h&&p.data[(py*p.w+px)*4+3]>30)return true}return false}
function initIslandMotion(){selectedIsland=false;document.querySelector('.gameworld').classList.toggle('motion-paused',mapMotionPaused);updateMotionButton();document.querySelectorAll('.island-surface').forEach(button=>{const img=button.querySelector('img');const cache=()=>{const key=img.getAttribute('src');if(islandPixels.has(key))return;const c=document.createElement('canvas');c.width=img.naturalWidth;c.height=img.naturalHeight;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(img,0,0);islandPixels.set(key,{w:c.width,h:c.height,data:ctx.getImageData(0,0,c.width,c.height).data})};if(img.complete&&img.naturalWidth)cache();else img.addEventListener('load',cache,{once:true});button.addEventListener('pointermove',e=>{const hit=alphaAt(button,e);button.classList.toggle('over-art',hit);button.closest('.island-unit').classList.toggle('is-hovered',hit)});button.addEventListener('pointerleave',()=>{button.classList.remove('over-art');button.closest('.island-unit').classList.remove('is-hovered')});})}
function activateIsland(event,i){if(selectedIsland)return;const button=event.currentTarget;if(event.detail!==0&&!alphaAt(button,event))return;selectedIsland=true;const unit=button.closest('.island-unit');unit.classList.add('is-selected');const r=button.getBoundingClientRect();button.style.setProperty('--click-x',`${event.detail?event.clientX-r.left:r.width/2}px`);button.style.setProperty('--click-y',`${event.detail?event.clientY-r.top:r.height/2}px`);setTimeout(()=>{unit.classList.remove('is-selected');selectedIsland=false;if(view==='map'&&!document.querySelector('#game').open){i<2?play(i):islandInfo(i)}},matchMedia('(prefers-reduced-motion: reduce)').matches?0:480)}
function toggleMapMotion(){mapMotionPaused=!mapMotionPaused;document.querySelector('.gameworld')?.classList.toggle('motion-paused',mapMotionPaused);updateMotionButton()}
function updateMotionButton(){const b=document.querySelector('.motion-toggle');if(b){b.textContent=mapMotionPaused?'▶ Bật chuyển động':'⏸ Dừng chuyển động';b.setAttribute('aria-pressed',String(mapMotionPaused))}}
